    private LoginValidator loginValidator;

    // Novas instâncias dos Managers
    private CursoManager cursoManager;
    private QuestionarioManager questionarioManager;

    // Credenciais do Admin (fixas conforme solicitado)
    private static final String ADMIN_EMAIL = "admin@admin.com";
    private static final String ADMIN_PASSWORD = "abracadabra";

    private TelaUsuario() throws InfraException{
        this.loginValidator = new LoginValidator();
        // Inicializa os managers aqui para garantir que os dados sejam carregados
        this.cursoManager = new CursoManager();
        this.questionarioManager = new QuestionarioManager();
    }

    // ... (main e showMenuLogin permanecem os mesmos) ...

    public static void main (String[] args) throws LoginInvalidException, InfraException {
        showMenuLogin();
